export function createCheckboxGroup(root) {
  const inputs=[...root.querySelectorAll('input[type="checkbox"]')];
  const status=root.querySelector('[data-checkbox-status]');
  if(!inputs.length || !(status instanceof HTMLElement)) throw new Error('Checkbox group markup is incomplete.');
  const update=()=>{const selected=inputs.filter(input=>input.checked).map(input=>input.value);status.textContent=selected.length?`Selected: ${selected.join(', ')}.`:'No notifications selected.';};
  inputs.forEach(input=>input.addEventListener('change',update));
  return {destroy(){inputs.forEach(input=>input.removeEventListener('change',update));}};
}
document.querySelectorAll('[data-component="checkbox-group"]').forEach(createCheckboxGroup);

