export function createValidatedField(root) {
  const form=root.querySelector('form');const input=root.querySelector('input');const error=root.querySelector('[data-field-error]');
  if(!(form instanceof HTMLFormElement)||!(input instanceof HTMLInputElement)||!(error instanceof HTMLElement))throw new Error('Validated field markup is incomplete.');
  const validate=()=>{const valid=input.validity.valid;input.setAttribute('aria-invalid',String(!valid));error.hidden=valid;return valid;};
  const submit=(event)=>{event.preventDefault();if(!validate())input.focus();};
  const clear=()=>{if(input.getAttribute('aria-invalid')==='true')validate();};
  form.addEventListener('submit',submit);input.addEventListener('input',clear);
  return{validate,destroy(){form.removeEventListener('submit',submit);input.removeEventListener('input',clear);}};
}
document.querySelectorAll('[data-component="validated-field"]').forEach(createValidatedField);

