export function createTabs(root) {
  const tabs=[...root.querySelectorAll('[role="tab"]')];const panels=[...root.querySelectorAll('[role="tabpanel"]')];
  if(!tabs.length||tabs.length!==panels.length)throw new Error('Tabs markup is incomplete.');
  const activate=(tab,{focus=true}={})=>{tabs.forEach((item,index)=>{const selected=item===tab;item.setAttribute('aria-selected',String(selected));item.tabIndex=selected?0:-1;panels[index].hidden=!selected;});if(focus)tab.focus();root.dispatchEvent(new CustomEvent('tabs:change',{detail:{id:tab.id}}));};
  const handleClick=(event)=>activate(event.currentTarget,{focus:false});
  const handleKeydown=(event)=>{const index=tabs.indexOf(event.currentTarget);let next=index;if(event.key==='ArrowRight')next=(index+1)%tabs.length;else if(event.key==='ArrowLeft')next=(index-1+tabs.length)%tabs.length;else if(event.key==='Home')next=0;else if(event.key==='End')next=tabs.length-1;else if(event.key==='Enter'||event.key===' '){event.preventDefault();activate(event.currentTarget);return;}else return;event.preventDefault();tabs[next].focus();};
  tabs.forEach(tab=>{tab.addEventListener('click',handleClick);tab.addEventListener('keydown',handleKeydown);});
  return{activate(index){if(tabs[index])activate(tabs[index]);},destroy(){tabs.forEach(tab=>{tab.removeEventListener('click',handleClick);tab.removeEventListener('keydown',handleKeydown);});}};
}
document.querySelectorAll('[data-component="tabs"]').forEach(createTabs);

